export type FunctionInvocationRequest = {
  /**
   * Payload to send to the Lambda function.
   *
   * If invoked with auth user token, Volcano automatically injects `__volcano_auth` context:
   * ```javascript
   * {
   * ...yourPayload,
   * __volcano_auth: {
   * user_id: "uuid",
   * email: "user@example.com",
   * project_id: "uuid",
   * role: "authenticated" | "anonymous"
   * }
   * }
   * ```
   *
   * Volcano also injects server-controlled request metadata as `__volcano_request`:
   * ```javascript
   * {
   * method: "POST",
   * headers: {
   * "Content-Type": "application/json",
   * "X-Client-Info": "volcano-sdk-js/2.0.0",
   * "X-Trace-Id": "caller-supplied-value"
   * }
   * }
   * ```
   * Authentication, cookies, hop-by-hop headers, proxy forwarding
   * headers, internal `X-Volcano-*` headers, and browser `Sec-*` headers
   * are not forwarded. Caller-supplied `__volcano_auth` and
   * `__volcano_request` values are always removed or replaced.
   *
   */
  payload?: {
    [key: string]: unknown;
  };
};

/**
 * Raw function response body returned by the invoked function.
 */
export type FunctionInvocationResponse = {
  [key: string]: unknown;
};

