/**
 * Declarative project configuration manifest (the JSON form of
 * volcano-config.yaml). Omitted sections are left untouched. Within
 * declared entries, omitted optional fields keep their current server
 * values (patch semantics). Declared collection keys are fully synced to
 * the manifest: `variables`, `buckets[].policies`, `auth.providers.oauth`,
 * `auth.email.templates`, and `functions[].schedulers` are reconciled to
 * exactly match, deleting resources absent from the manifest. Functions,
 * frontends, databases, and buckets are never created or deleted through
 * this manifest; entries referencing resources that do not exist are
 * skipped and reported.
 *
 */
export type ProjectConfig = {
  /**
   * Manifest schema version. Must be 1.
   */
  version: 1;
  project?: ProjectConfigProject;
  databases?: Array<ProjectConfigDatabase>;
  /**
   * Fully synced when declared - variables absent from this list are deleted.
   */
  variables?: Array<ProjectConfigVariable>;
  buckets?: Array<ProjectConfigBucket>;
  realtime?: ProjectConfigRealtime;
  auth?: ProjectConfigAuth;
  functions?: Array<ProjectConfigFunction>;
  frontends?: Array<ProjectConfigFrontend>;
};

/**
 * Per-resource report for a project config apply (or dry run).
 */
export type ProjectConfigApplyResult = {
  /**
   * True when the request was a dry run and no changes were made.
   */
  dry_run?: boolean;
  results: Array<ProjectConfigApplyResultEntry>;
  /**
   * Manifest entries referencing functions, frontends, databases, or
   * buckets that do not exist. Their configuration was not applied;
   * deploy/create the resource first, then re-apply.
   *
   */
  skipped: Array<ProjectConfigSkippedResource>;
  /**
   * Existing functions, frontends, databases, or buckets that have no
   * entry in the corresponding declared manifest section.
   *
   */
  missing: Array<ProjectConfigMissingResource>;
  summary: ProjectConfigApplySummary;
};

export type ProjectConfigApplyResultEntry = {
  /**
   * Manifest section the entry belongs to (e.g. variables, buckets, auth.providers.oauth).
   */
  section: string;
  /**
   * Resource name or key within the section. Empty for singleton sections.
   */
  name?: string;
  action: 'created' | 'updated' | 'deleted' | 'unchanged' | 'error';
  /**
   * Error detail when action is `error`.
   */
  error?: string;
  /**
   * Optional operational note (e.g. disabling realtime drops active connections).
   */
  notice?: string;
};

export type ProjectConfigApplySummary = {
  created: number;
  updated: number;
  deleted: number;
  unchanged: number;
  errors: number;
  skipped: number;
  missing: number;
};

