export type LogDeploymentRequestSelector = {
  /**
   * Optional deployment identifiers. Omit or send an empty array to include every deployment for the selected resources.
   */
  ids?: Array<string>;
};

/**
 * Edge Function log resource selector.
 */
export type LogFunctionRequestResource = {
  /**
   * Resource type to read logs for.
   */
  type: 'function';
  /**
   * Optional function identifiers. Omit or send an empty array to include every function in the project.
   */
  ids?: Array<string>;
  deployments?: LogDeploymentRequestSelector;
};

/**
 * Frontend log resource selector.
 */
export type LogFrontendRequestResource = {
  /**
   * Resource type to read logs for.
   */
  type: 'frontend';
  /**
   * Optional frontend identifiers. Omit or send an empty array to include every frontend in the project.
   */
  ids?: Array<string>;
  deployments?: LogDeploymentRequestSelector;
};

/**
 * Database runtime log resource selector. Deployment logs are not supported for databases.
 */
export type LogDatabaseRequestResource = {
  /**
   * Resource type to read logs for.
   */
  type: 'database';
  /**
   * Optional database identifiers. Omit or send an empty array to include every database in the project.
   */
  ids?: Array<string>;
};

/**
 * Resource selectors for project log reads.
 */
export type LogRequestResource =
  | ({
      type: 'function';
    } & LogFunctionRequestResource)
  | ({
      type: 'frontend';
    } & LogFrontendRequestResource)
  | ({
      type: 'database';
    } & LogDatabaseRequestResource);

/**
 * Resource that owns a historical log event.
 */
export type LogResource = {
  /**
   * Resource type that owns the log event.
   */
  type: 'function' | 'frontend' | 'database';
  /**
   * Resource ID that owns the log event.
   */
  id: string;
  /**
   * Resource name associated with the log event, when available.
   */
  name?: string;
};

/**
 * Deployment context associated with a historical deployment log event.
 */
export type LogDeployment = {
  /**
   * Deployment ID associated with the log event.
   */
  id: string;
  /**
   * Deployment stage that produced the log event, when available.
   */
  stage?: 'compile' | 'publish';
};

export type FunctionRuntimeDeployment = {
  /**
   * Source file extensions the CLI can use to detect this runtime.
   */
  file_extensions: Array<string>;
  /**
   * Archive path the CLI should use for a single-file function source.
   */
  entrypoint: string;
  /**
   * Handler symbol the CLI should submit when deploying this runtime.
   */
  handler: string;
  /**
   * Dependency manifest files the CLI should include for hosted builds.
   */
  dependency_manifests: Array<string>;
};

/**
 * Declarative project configuration manifest (the JSON form of
 * volcano-config.yaml). Omitted sections are left untouched. Within
 * declared entries, omitted optional fields keep their current server
 * values (patch semantics). Declared collection keys are fully synced to
 * the manifest: `variables`, `buckets[].policies`, `auth.providers.oauth`,
 * `auth.email.templates`, and `functions[].schedulers` are reconciled to
 * exactly match, deleting resources absent from the manifest. Functions,
 * frontends, databases, and buckets are never created or deleted through
 * this manifest; entries referencing resources that do not exist are
 * skipped and reported.
 *
 */
export type ProjectConfigWritable = {
  /**
   * Manifest schema version. Must be 1.
   */
  version: 1;
  project?: ProjectConfigProject;
  databases?: Array<ProjectConfigDatabase>;
  /**
   * Fully synced when declared - variables absent from this list are deleted.
   */
  variables?: Array<ProjectConfigVariable>;
  buckets?: Array<ProjectConfigBucket>;
  realtime?: ProjectConfigRealtime;
  auth?: ProjectConfigAuthWritable;
  functions?: Array<ProjectConfigFunction>;
  frontends?: Array<ProjectConfigFrontend>;
};

/**
 * Authentication settings, grouped like the dashboard auth-settings tabs.
 */
export type ProjectConfigAuthWritable = {
  tokens?: ProjectConfigAuthTokens;
  sessions?: ProjectConfigAuthSessions;
  signup?: ProjectConfigAuthSignup;
  rate_limits?: ProjectConfigAuthRateLimits;
  password?: ProjectConfigAuthPassword;
  password_reset?: ProjectConfigAuthPasswordReset;
  email_verification?: ProjectConfigAuthEmailVerification;
  cors?: ProjectConfigAuthCors;
  providers?: ProjectConfigAuthProvidersWritable;
  email?: ProjectConfigAuthEmailWritable;
  managed_pages?: ProjectConfigAuthManagedPages;
};

export type ProjectConfigAuthEmailWritable = {
  /**
   * Enable transactional email sending
   */
  enabled?: boolean;
  from?: ProjectConfigAuthEmailFrom;
  smtp?: ProjectConfigAuthEmailSmtpWritable;
  templates?: ProjectConfigEmailTemplates;
};

export type ProjectConfigAuthEmailSmtpWritable = {
  host?: string;
  port?: number;
  username?: string;
  /**
   * Write-only; omitted from config export.
   */
  password?: string;
  use_tls?: boolean;
};

export type ProjectConfigAuthProvidersWritable = {
  email_password?: ProjectConfigAuthEmailPasswordProvider;
  /**
   * Fully synced when declared - providers absent from this list are deleted.
   */
  oauth?: Array<ProjectConfigOAuthProviderWritable>;
};

export type ProjectConfigOAuthProviderWritable = {
  provider: 'google' | 'github' | 'microsoft' | 'apple' | 'device';
  enabled?: boolean;
  /**
   * Required for non-device providers. Server-generated for
   * `provider=device` (exported read-only, ignored on apply).
   *
   */
  client_id?: string;
  /**
   * Write-only; omitted from config export. Not used for `provider=device`.
   */
  client_secret?: string;
  /**
   * Not used for `provider=device`.
   */
  redirect_url?: string;
  scopes?: Array<string>;
};

/**
 * Storage bucket name
 */
export type BucketName = string;

/**
 * Database name (unique within project, lowercase letters, numbers, and underscores only)
 */
export type DatabaseName = string;

/**
 * Frontend deployment ID
 */
export type DeploymentId = string;

/**
 * Frontend ID
 */
export type FrontendId = string;

/**
 * Function ID
 */
export type FunctionId = string;

/**
 * Number of items per page (max 100)
 */
