/**
 * Page number (1-indexed)
 */
export type Page = number;

/**
 * Project ID
 */
export type ProjectId = string;

/**
 * Function scheduler ID
 */
export type SchedulerId = string;

/**
 * Variable name
 */
export type VariableName = string;

